"""Approximants whose LAL implementation bounds a component mass are generated by mass rescaling.

LAL's ``IMRPhenomNSBH`` refuses a neutron star heavier than 3 solar masses. An injection passes it
*detector-frame* masses, ``(1 + z) m``, so a 1.4 solar-mass neutron star at ``z = 1.2`` is already
refused, although the binary is well inside the model's calibration. A frequency-domain waveform in
general relativity depends on the masses only through ``M f`` and scales as ``M^2 / d`` in
amplitude, so ``h(f; M, d) = lam * h(lam f; M / lam, d / lam)`` for any ``lam``. The backend evaluates
the guarded approximant at ``M / lam`` on the frequency grid scaled by ``lam`` and rescales the
result; the references below generate the same binary without any rescaling.
"""

from __future__ import annotations

try:
    import lal
except ModuleNotFoundError as exc:  # Python 3.15: lalsuite does not install yet; its tests are skipped
    if exc.name != "lal":
        raise
    lal = None
import numpy as np
import pytest

from gwmock_signal.waveform.backends import lal as lal_backend
from gwmock_signal.waveform.backends.lal import LALSimulationBackend

_FS = 2048.0
_F_MIN = 20.0

#: A non-spinning neutron star-black hole binary, its tides and orientation.
_NSBH = {
    "spin_1z": 0.0,
    "spin_2z": 0.0,
    "lambda_2": 400.0,
    "inclination": 0.4,
    "coa_phase": 0.3,
}


def _generate(approximant: str, mass1: float, mass2: float, distance: float, **extra: float) -> np.ndarray:
    """Return the plus and cross polarizations of one binary, stacked."""
    waveform = LALSimulationBackend().generate_td_waveform(
        approximant,
        tc=0.0,
        sampling_frequency=_FS,
        minimum_frequency=_F_MIN,
        detector_frame_mass_1=mass1,
        detector_frame_mass_2=mass2,
        luminosity_distance=distance,
        **extra,
    )
    return np.stack([np.asarray(waveform["plus"].data), np.asarray(waveform["cross"].data)])


@pytest.mark.requires_lalsuite
def test_a_neutron_star_above_the_guard_in_the_detector_frame_is_generated() -> None:
    """A 1.4 solar-mass neutron star at z = 1.5 reaches LAL as 3.5 solar masses and still generates."""
    strain = _generate("IMRPhenomNSBH", 2.5 * 7.0, 2.5 * 1.4, 10000.0, **_NSBH)

    assert np.all(np.isfinite(strain))
    assert np.max(np.abs(strain)) > 0.0


@pytest.mark.requires_lalsuite
def test_rescaled_generation_equals_direct_generation_of_the_same_approximant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """With the guard lowered, a binary LAL accepts directly is rescaled, and both routes agree.

    The binary has a 2.8 solar-mass neutron star, which LAL accepts. Lowering the backend's guard
    to 2 solar masses forces the rescaled route for the same binary, so the two waveforms come from
    the same approximant through different arithmetic and must be equal.
    """
    direct = _generate("IMRPhenomNSBH", 14.0, 2.8, 500.0, **_NSBH)
    monkeypatch.setitem(lal_backend._LIGHTER_MASS_GUARDS, "IMRPhenomNSBH", 2.0)
    rescaled = _generate("IMRPhenomNSBH", 14.0, 2.8, 500.0, **_NSBH)

    peak = np.max(np.abs(direct))
    np.testing.assert_allclose(rescaled, direct, rtol=0.0, atol=1e-11 * peak)


@pytest.mark.requires_lalsuite
def test_rescaling_matches_direct_generation_for_an_unguarded_approximant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """The scaling identity holds for a second model, with spins, so it is not specific to one guard."""
    params = {"spin_1z": 0.6, "spin_2z": -0.3, "inclination": 1.1, "coa_phase": 2.0}
    direct = _generate("IMRPhenomD", 30.0, 8.0, 800.0, **params)
    monkeypatch.setitem(lal_backend._LIGHTER_MASS_GUARDS, "IMRPhenomD", 3.0)
    rescaled = _generate("IMRPhenomD", 30.0, 8.0, 800.0, **params)

    peak = np.max(np.abs(direct))
    np.testing.assert_allclose(rescaled, direct, rtol=0.0, atol=1e-11 * peak)


@pytest.mark.requires_lalsuite
def test_a_binary_inside_the_guard_is_not_rescaled(monkeypatch: pytest.MonkeyPatch) -> None:
    """Below the guard the approximant is called with the masses as given."""
    seen: list[float] = []
    original = lal_backend._mass_scale

    def spy(approximant: str, mass1: float, mass2: float) -> float:
        scale = original(approximant, mass1, mass2)
        seen.append(scale)
        return scale

    monkeypatch.setattr(lal_backend, "_mass_scale", spy)
    _generate("IMRPhenomNSBH", 14.0, 2.8, 500.0, **_NSBH)

    assert seen == [1.0]


def test_the_scale_brings_the_lighter_mass_inside_the_guard() -> None:
    """The scale is 1 inside the guard and puts the lighter mass at half the guard above it."""
    assert lal_backend._mass_scale("IMRPhenomNSBH", 14.0, 2.8) == 1.0
    assert lal_backend._mass_scale("IMRPhenomD", 40.0, 30.0) == 1.0
    scale = lal_backend._mass_scale("IMRPhenomNSBH", 20.0, 6.0)
    assert 6.0 / scale == pytest.approx(1.5, rel=1e-15)
    assert lal_backend._mass_scale("IMRPhenomNSBH", 6.0, 20.0) == scale


@pytest.mark.requires_lalsuite
def test_every_guarded_approximant_is_evaluated_in_the_frequency_domain() -> None:
    """The rescaling is exact only for frequency-domain approximants, so no other may be guarded."""
    import lalsimulation

    for approximant in lal_backend._LIGHTER_MASS_GUARDS:
        assert lalsimulation.SimInspiralImplementedFDApproximants(
            lalsimulation.GetApproximantFromString(approximant)
        ), approximant
